import { SalesRecord, KPIData, TopProduct, TopCustomer, MonthlyData, ProductShare } from '../types';

export const calculateKPIs = (salesData: SalesRecord[]): KPIData => {
  const totalRevenue = salesData.reduce((sum, record) => sum + record.revenue, 0);
  const totalTarget = salesData.reduce((sum, record) => sum + record.target, 0);
  const targetAchievement = totalTarget > 0 ? (totalRevenue / totalTarget) * 100 : 0;

  // Calculate month-over-month growth
  const currentMonth = salesData.filter(record => 
    new Date(record.date).getMonth() === new Date().getMonth()
  );
  const lastMonth = salesData.filter(record => {
    const recordDate = new Date(record.date);
    const currentDate = new Date();
    return recordDate.getMonth() === currentDate.getMonth() - 1;
  });

  const currentMonthRevenue = currentMonth.reduce((sum, record) => sum + record.revenue, 0);
  const lastMonthRevenue = lastMonth.reduce((sum, record) => sum + record.revenue, 0);
  
  const revenueGrowth = lastMonthRevenue > 0 
    ? ((currentMonthRevenue - lastMonthRevenue) / lastMonthRevenue) * 100 
    : 0;

  return {
    totalRevenue,
    targetAchievement,
    revenueGrowth
  };
};

export const getTopProducts = (salesData: SalesRecord[]): TopProduct[] => {
  const productMap = new Map<string, { revenue: number; units: number }>();
  
  salesData.forEach(record => {
    const existing = productMap.get(record.product) || { revenue: 0, units: 0 };
    productMap.set(record.product, {
      revenue: existing.revenue + record.revenue,
      units: existing.units + record.unitsSold
    });
  });

  const totalRevenue = Array.from(productMap.values()).reduce((sum, p) => sum + p.revenue, 0);
  
  return Array.from(productMap.entries())
    .map(([product, data]) => ({
      product,
      totalRevenue: data.revenue,
      unitsSold: data.units,
      percentage: (data.revenue / totalRevenue) * 100
    }))
    .sort((a, b) => b.totalRevenue - a.totalRevenue)
    .slice(0, 5);
};

export const getTopCustomers = (salesData: SalesRecord[]): TopCustomer[] => {
  const customerMap = new Map<string, { revenue: number; orders: number }>();
  
  salesData.forEach(record => {
    const existing = customerMap.get(record.client) || { revenue: 0, orders: 0 };
    customerMap.set(record.client, {
      revenue: existing.revenue + record.revenue,
      orders: existing.orders + 1
    });
  });

  const totalRevenue = Array.from(customerMap.values()).reduce((sum, c) => sum + c.revenue, 0);
  
  return Array.from(customerMap.entries())
    .map(([client, data]) => ({
      client,
      totalRevenue: data.revenue,
      orders: data.orders,
      percentage: (data.revenue / totalRevenue) * 100
    }))
    .sort((a, b) => b.totalRevenue - a.totalRevenue)
    .slice(0, 5);
};

export const getMonthlyData = (salesData: SalesRecord[]): MonthlyData[] => {
  const monthlyMap = new Map<string, { sales: number; target: number }>();
  
  salesData.forEach(record => {
    const month = new Date(record.date).toLocaleDateString('en-US', { month: 'short', year: 'numeric' });
    const existing = monthlyMap.get(month) || { sales: 0, target: 0 };
    monthlyMap.set(month, {
      sales: existing.sales + record.revenue,
      target: existing.target + record.target
    });
  });

  return Array.from(monthlyMap.entries())
    .map(([month, data]) => ({
      month,
      sales: data.sales,
      target: data.target
    }))
    .sort((a, b) => new Date(a.month).getTime() - new Date(b.month).getTime());
};

export const getProductShare = (salesData: SalesRecord[]): ProductShare[] => {
  const productMap = new Map<string, number>();
  
  salesData.forEach(record => {
    const existing = productMap.get(record.product) || 0;
    productMap.set(record.product, existing + record.revenue);
  });

  const totalRevenue = Array.from(productMap.values()).reduce((sum, revenue) => sum + revenue, 0);
  const colors = ['#3b82f6', '#ef4444', '#10b981', '#f59e0b', '#8b5cf6', '#06b6d4'];
  
  return Array.from(productMap.entries())
    .map(([product, revenue], index) => ({
      product,
      revenue,
      percentage: (revenue / totalRevenue) * 100,
      color: colors[index % colors.length]
    }))
    .sort((a, b) => b.revenue - a.revenue);
};

export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
};

export const formatPercentage = (value: number): string => {
  return `${value.toFixed(1)}%`;
};
